def mark_historical_years_as_processed(apps, schema_editor):
    academic_years = apps.get_model("core", "AcademicYear")
    students = apps.get_model("core", "Student")
    now = timezone.now()
    academic_years.objects.filter(
        is_current=False,
        end_date__lt=timezone.localdate(),
        students_phased_out_at__isnull=True,
    ).update(students_phased_out_at=now)
    current_year = academic_years.objects.filter(is_current=True).first()
    if current_year:
        students.objects.filter(
            status="Enrolled",
            class_group__name__istartswith="3",
            expected_completion_year__isnull=True,
        ).update(expected_completion_year_id=current_year.pk)


